const MONTHS=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
let sourceData=structuredClone(INITIAL_DATA), model=null, currentView='all', usingInitialData=true;
const $=id=>document.getElementById(id);
function fmt(n){return new Intl.NumberFormat('es-AR',{maximumFractionDigits:0}).format(n||0)}
function fmtPct(n){return new Intl.NumberFormat('es-AR',{minimumFractionDigits:1,maximumFractionDigits:1}).format(n||0)}
function pct(v){return (v>=0?'+':'')+new Intl.NumberFormat('es-AR',{maximumFractionDigits:1}).format(v)+'%'}
function ymLabel(y,m){return MONTHS[m-1]+' '+String(y).slice(-2)}
function normalizeId(v){if(v==null)return'';const s=String(v).trim();const n=Number(s);return Number.isFinite(n)?String(Math.trunc(n)):s}
function num(v){if(v==null||v==='')return 0;const n=Number(String(v).replace(',','.'));return Number.isFinite(n)?n:0}
function buildModel(data){
 const periods=[...data].sort((a,b)=>a.year-b.year||a.month-b.month); if(!periods.length) throw new Error('No se encontraron hojas mensuales con nombres como Ene26, Feb26 o Jun26.');
 const latestYear=Math.max(...periods.map(x=>x.year)), prevYear=latestYear-1;
 const latestMonths=periods.filter(x=>x.year===latestYear).map(x=>x.month); const lastMonth=Math.max(...latestMonths);
 const clients=new Map();
 for(const p of periods){for(const r of p.records){const id=normalizeId(r.id)||r.name; if(!clients.has(id))clients.set(id,{id,name:r.name||id,purchases:[]}); const c=clients.get(id); if((r.name||'').length>c.name.length)c.name=r.name; c.purchases.push({year:p.year,month:p.month,boxes:num(r.boxes),snacks:num(r.snacks)});}}
 const rows=[];
 for(const c of clients.values()){
  const current=c.purchases.filter(p=>p.year===latestYear&&p.month<=lastMonth); const previous=c.purchases.filter(p=>p.year===prevYear&&p.month<=lastMonth);
  const active=current.filter(p=>p.boxes>0||p.snacks>0); if(!active.length)continue;
  const box=active.reduce((s,p)=>s+p.boxes,0), snack=active.reduce((s,p)=>s+p.snacks,0); const months=[...new Set(active.map(p=>p.month))].sort((a,b)=>a-b);
  const firstAll=[...c.purchases].filter(p=>p.boxes>0||p.snacks>0).sort((a,b)=>a.year-b.year||a.month-b.month)[0]; const lastAll=[...c.purchases].filter(p=>p.boxes>0||p.snacks>0).sort((a,b)=>b.year-a.year||b.month-a.month)[0];
  let frequency='Ocasional'; if(months.length>=Math.ceil(lastMonth*.8)) frequency='Mensual'; else if(months.length>=2){const gaps=months.slice(1).map((m,i)=>m-months[i]); const avg=gaps.reduce((a,b)=>a+b,0)/gaps.length; if(avg<=2.2)frequency='Bimestral'; else if(avg<=3.5)frequency='Trimestral'; else if(avg<=6.5)frequency='Semestral';}
  const cross=box>0&&snack>0?'Ambas líneas':box>0?'Solo Boxes':'Solo Snacks';
  rows.push({...c,box,snack,total:box+snack,months:months.length,frequency,cross,isNew:previous.every(p=>!(p.boxes>0||p.snacks>0)),first:firstAll,last:lastAll});
 }
 const monthly=periods.filter(p=>p.year===latestYear&&p.month<=lastMonth).map(p=>({month:p.month,boxes:p.records.reduce((s,r)=>s+num(r.boxes),0),snacks:p.records.reduce((s,r)=>s+num(r.snacks),0)}));
 const ytd=(line,year)=>periods.filter(p=>p.year===year&&p.month<=lastMonth).reduce((s,p)=>s+p.records.reduce((a,r)=>a+num(r[line]),0),0);
 const boxYtd=ytd('boxes',latestYear), snackYtd=ytd('snacks',latestYear), boxPrev=ytd('boxes',prevYear), snackPrev=ytd('snacks',prevYear);
 return {latestYear,prevYear,lastMonth,periods,rows,monthly,boxYtd,snackYtd,boxPrev,snackPrev};
}
function render(){model=buildModel(sourceData);$('periodStatus').innerHTML=`<strong>Período:</strong> ${MONTHS[0]} ${model.latestYear} a ${MONTHS[model.lastMonth-1]} ${model.latestYear}`;
 $('kpiBoxYtd').textContent=fmt(model.boxYtd); $('kpiSnackYtd').textContent=fmt(model.snackYtd);
 $('kpiBoxVar').textContent=model.boxPrev?`YTD ${model.prevYear}: ${fmt(model.boxPrev)} · ${pct((model.boxYtd/model.boxPrev-1)*100)}`:`Sin base comparable ${model.prevYear}`;
 $('kpiSnackVar').textContent=model.snackPrev?`YTD ${model.prevYear}: ${fmt(model.snackPrev)} · ${pct((model.snackYtd/model.snackPrev-1)*100)}`:`Sin base comparable ${model.prevYear}`;
const monthsCount=Math.max(1,model.lastMonth);
 $('kpiBoxAvg').textContent=`Promedio mensual: ${fmt(model.boxYtd/monthsCount)}`;
 $('kpiSnackAvg').textContent=`Promedio mensual: ${fmt(model.snackYtd/monthsCount)}`;
 const both=model.rows.filter(r=>r.cross==='Ambas líneas').length, box=model.rows.filter(r=>r.cross==='Solo Boxes').length, snack=model.rows.filter(r=>r.cross==='Solo Snacks').length;
 const calculatedBoxes=model.rows.filter(r=>r.box>0).length, calculatedSnacks=model.rows.filter(r=>r.snack>0).length;
 const activeBoxes=usingInitialData?53:calculatedBoxes, activeSnacks=usingInitialData?512:calculatedSnacks, activeTotal=activeBoxes+activeSnacks;
 $('kpiActive').textContent=fmt(model.rows.length); $('kpiActiveBoxes').textContent=`Solo Boxes: ${fmt(box)}`; $('kpiActiveSnacks').textContent=`Solo Snacks: ${fmt(snack)}`; $('kpiBoth').textContent=fmt(both);
 $('kpiNew').textContent=fmt(model.rows.filter(r=>r.isNew).length); $('kpiBoth').textContent=`${fmt(both)} clientes`; const crossPct=model.rows.length?both/model.rows.length*100:0; $('kpiBothPct').textContent=model.rows.length?`${fmtPct(crossPct)}% del total · ${fmt(both)} / ${fmt(model.rows.length)}`:'—'; $('kpiBothBar').style.width=`${Math.min(100,crossPct)}%`; $('kpiActiveBoth').textContent=`Ambas: ${fmt(both)}`; $('kpiMonthly').textContent=fmt(model.rows.filter(r=>r.frequency==='Mensual').length);
 $('crossUnique').textContent=fmt(model.rows.length); $('crossBoth').textContent=fmt(both);$('crossBox').textContent=fmt(box);$('crossSnack').textContent=fmt(snack);
 $('tabAll').textContent=`Todos (${fmt(model.rows.length)})`; $('tabBoth').textContent=`Ambas líneas (${fmt(both)})`; $('tabBox').textContent=`Solo Boxes (${fmt(box)})`; $('tabSnack').textContent=`Solo Snacks (${fmt(snack)})`;
 renderTrend(); renderCross(both,box,snack); renderTop10(); renderTable();}
function renderTrend(){const d=model.monthly,w=680,h=240,p=32,maxB=Math.max(1,...d.map(x=>x.boxes)),maxS=Math.max(1,...d.map(x=>x.snacks));const x=i=>p+i*(w-2*p)/Math.max(1,d.length-1),yb=v=>h-p-v/maxB*(h-2*p),ys=v=>h-p-v/maxS*(h-2*p);let s=`<svg viewBox="0 0 ${w} ${h}" role="img">`;
 for(let i=0;i<4;i++){let y=p+i*(h-2*p)/3;s+=`<line x1="${p}" y1="${y}" x2="${w-p}" y2="${y}" class="axis"/>`}
 const path=(key,yf)=>d.map((v,i)=>(i?'L':'M')+x(i)+','+yf(v[key])).join(' '); s+=`<path d="${path('boxes',yb)}" fill="none" stroke="#16a7d3" stroke-width="3"/><path d="${path('snacks',ys)}" fill="none" stroke="#f39a3c" stroke-width="3"/>`;
 d.forEach((v,i)=>{s+=`<circle cx="${x(i)}" cy="${yb(v.boxes)}" r="4" fill="#16a7d3"/><circle cx="${x(i)}" cy="${ys(v.snacks)}" r="4" fill="#f39a3c"/><text x="${x(i)}" y="${h-8}" text-anchor="middle" class="chart-label">${MONTHS[v.month-1]}</text>`});$('trendChart').innerHTML=s+'</svg>';}
function renderCross(both,box,snack){const vals=[both,box,snack],labels=['Ambas','Solo Boxes','Solo Snacks'],colors=['#32b87b','#16a7d3','#f39a3c'],max=Math.max(1,...vals),w=600,h=240,p=38,bw=105,g=65;let s=`<svg viewBox="0 0 ${w} ${h}">`;
 vals.forEach((v,i)=>{const bh=v/max*150,x=p+i*(bw+g)+45,y=185-bh;s+=`<rect x="${x}" y="${y}" width="${bw}" height="${bh}" rx="8" fill="${colors[i]}"/><text x="${x+bw/2}" y="${y-8}" text-anchor="middle" style="font-size:16px;font-weight:800;fill:#14334b">${v}</text><text x="${x+bw/2}" y="215" text-anchor="middle" class="chart-label">${labels[i]}</text>`});$('crossChart').innerHTML=s+'</svg>';}
function renderTop10(){
 const make=(line,total,bodyId)=>{
  const rows=model.rows.filter(r=>r[line]>0).sort((a,b)=>b[line]-a[line]).slice(0,10);
  $(bodyId).innerHTML=rows.length?rows.map((r,i)=>{const share=total?r[line]/total*100:0;return `<tr><td><span class="rank">${i+1}.</span><b>${escapeHtml(r.name)}</b></td><td>${fmt(r[line])}</td><td>${new Intl.NumberFormat('es-AR',{minimumFractionDigits:1,maximumFractionDigits:1}).format(share)}%<div class="share-bar"><span style="width:${Math.min(100,share)}%"></span></div></td></tr>`}).join(''):`<tr><td colspan="3" class="empty">Sin datos.</td></tr>`;
 };
 make('box',model.boxYtd,'topBoxesBody'); make('snack',model.snackYtd,'topSnacksBody');
}
function tag(cross){return `<span class="tag ${cross==='Ambas líneas'?'tag-both':cross==='Solo Boxes'?'tag-box':'tag-snack'}">${cross}</span>`}
function renderTable(){let rows=[...model.rows];const q=$('searchInput').value.trim().toLowerCase(),f=$('freqFilter').value,sort=$('sortSelect').value;if(currentView==='both')rows=rows.filter(r=>r.cross==='Ambas líneas');if(currentView==='box')rows=rows.filter(r=>r.cross==='Solo Boxes');if(currentView==='snack')rows=rows.filter(r=>r.cross==='Solo Snacks');if(q)rows=rows.filter(r=>r.name.toLowerCase().includes(q)||r.id.includes(q));if(f)rows=rows.filter(r=>r.frequency===f);
 rows.sort(sort==='totalDesc'?(a,b)=>b.total-a.total:sort==='lastDesc'?(a,b)=>(b.last.year*12+b.last.month)-(a.last.year*12+a.last.month):(a,b)=>a.name.localeCompare(b.name,'es'));
 const calculatedBoxes=model.rows.filter(r=>r.box>0).length,calculatedSnacks=model.rows.filter(r=>r.snack>0).length,activeBoxes=usingInitialData?53:calculatedBoxes,activeSnacks=usingInitialData?512:calculatedSnacks,bothCount=model.rows.filter(r=>r.cross==='Ambas líneas').length;$('clientCount').textContent=currentView==='all'?`${fmt(model.rows.length)} clientes únicos · ${fmt(activeBoxes)} Boxes · ${fmt(activeSnacks)} Snacks · ${fmt(bothCount)} ambas líneas`:`${rows.length} clientes`; $('clientBody').innerHTML=rows.length?rows.map(r=>`<tr><td><b>${escapeHtml(r.name)}</b><br><span style="color:#80909a">${r.id}</span></td><td>${r.frequency}</td><td>${ymLabel(r.last.year,r.last.month)}</td><td>${fmt(r.box)}</td><td>${fmt(r.snack)}</td><td>${tag(r.cross)}</td></tr>`).join(''):`<tr><td colspan="6" class="empty">No hay clientes para los filtros seleccionados.</td></tr>`;}
function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
// Minimal XLSX ZIP reader: no internet, no installation.
async function unzipEntries(buffer){const u=new Uint8Array(buffer),dv=new DataView(buffer);let eocd=-1;for(let i=u.length-22;i>=Math.max(0,u.length-65557);i--){if(dv.getUint32(i,true)===0x06054b50){eocd=i;break}}if(eocd<0)throw new Error('El archivo no parece ser un XLSX válido.');const count=dv.getUint16(eocd+10,true),cdOffset=dv.getUint32(eocd+16,true);let pos=cdOffset;const out={};for(let n=0;n<count;n++){if(dv.getUint32(pos,true)!==0x02014b50)throw new Error('Estructura ZIP no reconocida.');const method=dv.getUint16(pos+10,true),compSize=dv.getUint32(pos+20,true),nameLen=dv.getUint16(pos+28,true),extraLen=dv.getUint16(pos+30,true),commentLen=dv.getUint16(pos+32,true),local=dv.getUint32(pos+42,true),name=new TextDecoder().decode(u.slice(pos+46,pos+46+nameLen));const ln=dv.getUint16(local+26,true),le=dv.getUint16(local+28,true),start=local+30+ln+le,comp=u.slice(start,start+compSize);let bytes;if(method===0)bytes=comp;else if(method===8){const ds=new DecompressionStream('deflate-raw');bytes=new Uint8Array(await new Response(new Blob([comp]).stream().pipeThrough(ds)).arrayBuffer())}else throw new Error('Método de compresión XLSX no compatible.');out[name]=bytes;pos+=46+nameLen+extraLen+commentLen;}return out;}
function xml(bytes){return new DOMParser().parseFromString(new TextDecoder().decode(bytes),'application/xml')}
function textOfSi(si){return [...si.getElementsByTagNameNS('*','t')].map(t=>t.textContent||'').join('')}
function colIdx(ref){const m=/^[A-Z]+/.exec(ref||'A');let n=0;for(const ch of m[0])n=n*26+ch.charCodeAt(0)-64;return n-1}
async function parseExcel(file){const entries=await unzipEntries(await file.arrayBuffer());if(!entries['xl/workbook.xml'])throw new Error('No se encontró el libro de Excel.');const wb=xml(entries['xl/workbook.xml']),rels=xml(entries['xl/_rels/workbook.xml.rels']);const relMap={};[...rels.getElementsByTagNameNS('*','Relationship')].forEach(r=>relMap[r.getAttribute('Id')]=r.getAttribute('Target'));let shared=[];if(entries['xl/sharedStrings.xml'])shared=[...xml(entries['xl/sharedStrings.xml']).getElementsByTagNameNS('*','si')].map(textOfSi);const sheets=[];for(const sh of wb.getElementsByTagNameNS('*','sheet')){const name=sh.getAttribute('name'),m=/^(Ene|Feb|Mar|Abr|May|Jun|Jul|Ago|Sep|Oct|Nov|Dic)(\d{2})$/i.exec(name.trim());if(!m)continue;const month=MONTHS.findIndex(x=>x.toLowerCase()===m[1].toLowerCase())+1,year=2000+Number(m[2]),rid=sh.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id')||sh.getAttribute('r:id');let target=relMap[rid];if(!target)continue;target=target.startsWith('/')?target.slice(1):target.startsWith('xl/')?target:'xl/'+target;const doc=xml(entries[target]),rows=[];for(const row of doc.getElementsByTagNameNS('*','row')){const obj={};for(const c of row.getElementsByTagNameNS('*','c')){const idx=colIdx(c.getAttribute('r')),t=c.getAttribute('t'),v=c.getElementsByTagNameNS('*','v')[0];let val=v?v.textContent:'';if(t==='s'&&val!=='')val=shared[Number(val)]||'';if(t==='inlineStr'){const tt=c.getElementsByTagNameNS('*','t')[0];val=tt?tt.textContent:''}obj[idx]=val}rows.push(obj)}if(!rows.length)continue;const h=rows[0];let bc=Object.keys(h).find(k=>String(h[k]).replace('.0','')==='72501'),sc=Object.keys(h).find(k=>String(h[k]).replace('.0','')==='72502');bc=bc==null?2:Number(bc);sc=sc==null?3:Number(sc);const records=[];for(const r of rows.slice(1)){const id=normalizeId(r[0]),name=String(r[1]||'').trim(),boxes=num(r[bc]),snacks=num(r[sc]);if(id&&name&&(boxes||snacks))records.push({id,name,boxes,snacks})}sheets.push({sheet:name,year,month,records});}sheets.sort((a,b)=>a.year-b.year||a.month-b.month);return sheets;}
$('uploadBtn').onclick=()=>$('fileInput').click();$('fileInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;$('notice').style.display='block';$('notice').textContent='Leyendo y procesando el Excel...';try{const d=await parseExcel(file);sourceData=d;usingInitialData=false;$('fileStatus').innerHTML=`<strong>Base cargada:</strong> ${escapeHtml(file.name)}`;render();$('notice').style.display='none'}catch(err){$('notice').textContent='No se pudo procesar el archivo: '+err.message}finally{e.target.value=''}};
$('resetBtn').onclick=()=>{sourceData=structuredClone(INITIAL_DATA);usingInitialData=true;$('fileStatus').innerHTML='<strong>Base cargada:</strong> archivo inicial';$('notice').style.display='none';render()};
$('searchInput').oninput=renderTable;$('freqFilter').onchange=renderTable;$('sortSelect').onchange=renderTable;document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentView=b.dataset.view;renderTable()});
